  ('671997','14220 DESIERTO BUENO AVE','Horizon City','79928',31.65797,-106.19608,'CASTILLO ROBERT H S','14220 DESIERTO BUENO AVE','Horizon City','TX','79928',false,201737,'BLK 46 RANCHO DESIERTO BELLO 8 LOT 6','2026-12-01','27301'),
