  ('675169','11277 CIELO MAR DR','Socorro','79927',31.66541,-106.25449,'RAMIREZ MARIA D','11277 CIELO MAR DR','Socorro','TX','79927',false,238708,'BLK 1 CIELO DEL RIO 2 AMENDING LOT 34','2026-12-01','27243'),
  ('677381','14829 BOBBY JOE HILL DR','El Paso','79938',31.79776,-106.20478,'HOLGUIN MANUEL A & FIGUEROA LAURA Y','14829 BOBBY JOE HILL DR','El Paso','TX','79938',false,243121,'BLK 476 TIERRA DEL ESTE 77 LOT 8','2026-12-01','27267')
),
p as (
  insert into parcels (org_id, epcad_property_id, address, city, state, zip, lat, lng, market_value, legal_description, source, notes, tags)
  select org.id, s.prop_id, s.address, s.city, 'TX', s.zip, s.lat, s.lng, s.value, s.legal, 'county_foreclosure_map',
    'County Clerk foreclosure posting: sale ' || to_char(s.sale_date::date, 'Mon DD, YYYY') || '.',
    case when s.absentee then array['foreclosure','absentee'] else array['foreclosure'] end::text[]
  from src s, org
  on conflict (org_id, epcad_property_id) do update set
    lat = coalesce(parcels.lat, excluded.lat), lng = coalesce(parcels.lng, excluded.lng),
    zip = coalesce(parcels.zip, excluded.zip), legal_description = coalesce(parcels.legal_description, excluded.legal_description),
    market_value = coalesce(parcels.market_value, excluded.market_value),
    tags = (select array(select distinct unnest(parcels.tags || excluded.tags))),
    notes = case when coalesce(parcels.notes, '') like '%County Clerk foreclosure posting%' then parcels.notes else concat_ws(E'\n', parcels.notes, excluded.notes) end,
    updated_at = now()
  returning id, epcad_property_id
),
o as (
  insert into owners (org_id, parcel_id, name, mailing_address, mailing_city, mailing_state, mailing_zip, is_absentee)
  select (select id from org), p.id, s.owner, s.m_addr, s.m_city, s.m_state, s.m_zip, s.absentee
  from src s join p on p.epcad_property_id = s.prop_id
  where s.owner is not null and not exists (select 1 from owners x where x.parcel_id = p.id)
  returning parcel_id
),
f as (
  insert into foreclosures (org_id, parcel_id, sale_date, sale_location, source_url)
  select (select id from org), p.id, s.sale_date::date, 'El Paso County Courthouse, 500 E San Antonio Ave (first Tuesday, 10 AM to 4 PM)',
    'https://apps.epcountytx.gov/publicrecords/Foreclosures/DisplayMap?foreclosureId=' || s.fc_id
  from src s join p on p.epcad_property_id = s.prop_id
  where not exists (select 1 from foreclosures x where x.parcel_id = p.id and x.sale_date = s.sale_date::date)
  returning parcel_id
),
lst as (
  insert into lists (org_id, name, description)
  select org.id, n.name, n.descr from org, (values
    ('Remates 1 dic 2026', 'Casas en la lista de remates del County Clerk para la venta del 1 de diciembre de 2026.'),
    ('Remates 5 ene 2027', 'Avisos de remate para la venta del 5 de enero de 2027 registrados hasta el 24 de noviembre. Se siguen registrando hasta el 15 de diciembre.')) n(name, descr)
  where not exists (select 1 from lists x where x.org_id = org.id and x.name = n.name)
  returning id, name
),
lid as (select id, name from lst union all select x.id, x.name from lists x, org where x.org_id = org.id and x.name in ('Remates 1 dic 2026', 'Remates 5 ene 2027')),
li as (
  insert into list_items (org_id, list_id, parcel_id)
  select (select id from org), (select id from lid where name = case when s.sale_date = '2026-12-01' then 'Remates 1 dic 2026' else 'Remates 5 ene 2027' end limit 1), p.id
  from src s join p on p.epcad_property_id = s.prop_id
  on conflict do nothing
  returning parcel_id
)
select (select count(*) from p) as properties, (select count(*) from o) as owners_added, (select count(*) from f) as sale_dates_added, (select count(*) from li) as in_lists;
